    /// <param name="xtokst">De af te trekken bedragen</param>
    /// <param name="xto">Bruto of netto van af te trekken bedragen</param>
    public void Aftrekken(EXto xtoDoel, BXtoKst xtokst, EXto xto)
    {
        if (m_Vlt != xtokst.m_Vlt)
            throw new OngelijkeValutaException();

        for (int index = c_AtlKst - 1; index >= 0; index--)
        {
            m_XtoKst[(int)xtoDoel, index] -= xtokst.m_XtoKst[(int)xto, index];
