    public static BBegrotingBladFunctie.EFunctieSoort MaakBgrBladFieSoort(string naam)
    {
        BBegrotingBladFunctie.EFunctieSoort bfs;
        switch (naam)
        {
            case "TOT": bfs = BBegrotingBladFunctie.EFunctieSoort.Totaal; break;
            case "SCT": bfs = BBegrotingBladFunctie.EFunctieSoort.SectieTotaal; break;
            case BBgrBldFieVbd.c_SoortVastBedragBtwOnbepaald:
            case BBgrBldFieVbd.c_SoortVastBedragBtwHoog:
            case BBgrBldFieVbd.c_SoortVastBedragBtwLaag: bfs = BBegrotingBladFunctie.EFunctieSoort.VastBedrag; break;
            case "STL":     // verouderd, is nu:
            case "TTL": bfs = BBegrotingBladFunctie.EFunctieSoort.TussenTotaal; break;
            case "SOP":     // verouderd, is nu:
            case "OOP": bfs = BBegrotingBladFunctie.EFunctieSoort.OpslagOverOpslag; break;
            case "TOP": bfs = BBegrotingBladFunctie.EFunctieSoort.TotaalOpslagPost; break;
            case "VZP": bfs = BBegrotingBladFunctie.EFunctieSoort.Verzamelpost; break;
            case "EHP": bfs = BBegrotingBladFunctie.EFunctieSoort.Eenheidsprijs; break;
            case "CMT": bfs = BBegrotingBladFunctie.EFunctieSoort.Commentaar; break;
            case BBgrBldFieGrondslagBtwGeen.c_SoortGrondslagBtwGeen: bfs = BBegrotingBladFunctie.EFunctieSoort.GrondslagBtwGeen; break;
            case BBgrBldFieGrondslagBtwHoog.c_SoortGrondslagBtwHoog: bfs = BBegrotingBladFunctie.EFunctieSoort.GrondslagBtwHoog; break;
            case BBgrBldFieGrondslagBtwLaag.c_SoortGrondslagBtwLaag: bfs = BBegrotingBladFunctie.EFunctieSoort.GrondslagBtwLaag; break;
            case BBgrBldFieOpslagBtwHoog.c_SoortOpslagBtwHoog: bfs = BBegrotingBladFunctie.EFunctieSoort.OpslagBtwHoog; break;
            case BBgrBldFieOpslagBtwLaag.c_SoortOpslagBtwLaag: bfs = BBegrotingBladFunctie.EFunctieSoort.OpslagBtwLaag; break;
            case BBgrBldFieBtw.c_SoortTotaalBtw: bfs = BBegrotingBladFunctie.EFunctieSoort.TotaalBtw; break;

            default: throw new OnbekendeKostensoortException();
        }
        return bfs;
    }
