    public enum EVergelijk : int
    {
        hetzelfde = 0,
        ntoarb = 2,
        ntomta = 4,
        ntomte = 8,
        ntooda = 16,
        ntostr = 32,
        ntotot = 64,
        btoarb = 128,
        btomta = 256,
        btomte = 512,
        btooda = 1024,
        btostr = 2048,
        btotot = 4096
    }

    internal EVergelijk Vergelijk(BXtoKst xtoKst2)
    {
        EVergelijk gelijk = EVergelijk.hetzelfde;  // zijn exact hetzelfde
        if (BVergelijk.VerslagMetData())
        {
            if (_afronden.Getal(this[EXto.Nto, EKst.Arb].Waarde, 5) != _afronden.Getal(xtoKst2[EXto.Nto, EKst.Arb].Waarde, 5)) gelijk |= EVergelijk.ntoarb;
            if (_afronden.Getal(this[EXto.Nto, EKst.Mta].Waarde, 5) != _afronden.Getal(xtoKst2[EXto.Nto, EKst.Mta].Waarde, 5)) gelijk |= EVergelijk.ntomta;
            if (_afronden.Getal(this[EXto.Nto, EKst.Mte].Waarde, 5) != _afronden.Getal(xtoKst2[EXto.Nto, EKst.Mte].Waarde, 5)) gelijk |= EVergelijk.ntomte;
            if (_afronden.Getal(this[EXto.Nto, EKst.Oda].Waarde, 5) != _afronden.Getal(xtoKst2[EXto.Nto, EKst.Oda].Waarde, 5)) gelijk |= EVergelijk.ntooda;
            if (_afronden.Getal(this[EXto.Nto, EKst.Str].Waarde, 5) != _afronden.Getal(xtoKst2[EXto.Nto, EKst.Str].Waarde, 5)) gelijk |= EVergelijk.ntostr;
            if (_afronden.Getal(this[EXto.Nto, EKst.Aks].Waarde, 5) != _afronden.Getal(xtoKst2[EXto.Nto, EKst.Aks].Waarde, 5)) gelijk |= EVergelijk.ntotot;
