        public BOpdracht? WijzigDoubleBgrRegel(int stuIndex, BBegrotingsRegel.EGegeven gegevenNr, double waarde, bool uitMeting)
        {
            IBegrotingsRegel? bgrRegel = _Stu[stuIndex]._Regel;
            BOpdracht? opdracht = bgrRegel?.MaakWijzigDoubleOpdracht(stuIndex, gegevenNr, waarde, uitMeting);

            if (opdracht == null)
                return null;

            if (!opdracht.Uitvoeren(this))
                return null;

            if (!m_Snel)
            {
                if (gegevenNr == BBegrotingsRegel.EGegeven.hvh ||
                    gegevenNr == BBegrotingsRegel.EGegeven.postprijs ||
                    gegevenNr == BBegrotingsRegel.EGegeven.enhprs ||
                    gegevenNr == BBegrotingsRegel.EGegeven.fachvh ||
                    gegevenNr == BBegrotingsRegel.EGegeven.prodfactor)
                {
                    if (_BrinkKostenbestandEigenschappenOnderhoud?._MJOBActiefBerekenen == true)
                    {
                        // Direct de regel berekenen.
                        RekenenMjobContanteWaardeInvestering(bgrRegel);
                    }
                    else
                    {
                        // Parameter op false zetten.
                        _MjobContanteWaardeIsActueel = false;
                    }
                }

                if (opdracht._Rekenen)
                    Rekenen(ERekendiepte.Wijzigingen);

                _OpdrachtVzl.Aanmelden(opdracht);
            }

            opdracht._RegelNummer = stuIndex;
            _Context = opdracht._Context;

            return opdracht;
        }

        /// <summary>
        /// Wijzig de middelcode van een kostenpost
        /// </summary>
        /// <param name="kostenpost">De kostenpost waarvan de middelcode/calculatiecode moet wijzigen</param>
        /// <param name="midcde">De nieuwe middelcode</param>
        /// <param name="rekenen">true: de begroting moet opnieuw worden doorgerekend</param>
        /// <returns>true: de middelcode van de kostenpost is gewijzigd</returns>
        public BOpdracht? WijzigMidCde(BKostenpost kostenpost, string? midcde, out bool rekenen)
        {
            rekenen = false;
            if (_VttId == kostenpost._Id && _Umc)
                return null;

            int stuIndex = _Stu.ZoekKostenpost(kostenpost._Id);
            BWijzigMiddelCode opdracht = new BWijzigMiddelCode(stuIndex, midcde);
