                if (meetstaat._Model?._ModelId == model._ModelId)
                {
                    LeesMeetstaat(meetstaat);

                    Debug.Assert(meetstaat.Begroting == this, "BBegroting.GewijzigdModel() - ander meetstaatdocument");
