        private IBegrotingsRegel? MaakNieuwElement(int stuIndex)
        {
            BStructuurRegel sturgl = _Stu[stuIndex];
            int oudid = sturgl._Id;
            int oudniv = sturgl._Niveau;

            int nieuwid = GeefNieuwId();
            BElement element = sturgl._Regel == null
                ? new BElement(nieuwid, _VltId, this) { _Oms = BStatics.c_Bedrijf }
                : new BElement(nieuwid, (BElement)sturgl._Regel, null) { Begroting = this };
            var sturegelnieuw = new BStructuurRegel(element, sturgl._PrtId);

            sturegelnieuw._Niveau = sturgl._Niveau;
            sturegelnieuw._Regel?.ZetMutatieStatus(BewaarItemMutatieStatus.Nieuw);

            _Stu.VerwijderdeStructuurRegelToevoegen(sturgl);
            _Stu.Vervangen(sturegelnieuw, stuIndex);
            WijzigKinderen(stuIndex, oudid, nieuwid, oudniv);

            return sturegelnieuw._Regel;
        }

