        public bool GeefOnderbouwingstype(string stuurcode, ref EOnderbouwing type)
        {
            if (stuurcode.TrimEnd().Length == 0 ||
               char.IsLetter(stuurcode, 0) ||
               stuurcode[0] == BBegrotingsRegel.c_cStkCorrectie)  // '$'
            {
                type = EOnderbouwing.Kostenpost;
            }
            else
            {
                switch (stuurcode[0])
                {
                    //case BBegrotingsRegel.c_cStkPassief: // ',' tijdelijke waarde, wordt omgezet in status PASSIEF
                    case BBegrotingsRegel.c_cStkVoorlopig:
                        type = EOnderbouwing.Kostenpost;
                        break; // '?'

                    case BBegrotingsRegel.c_cStkOpslag:
                    case BBegrotingsRegel.c_cStkSub:
                    case BBegrotingsRegel.c_cStkEltTtot:
                    case BBegrotingsRegel.c_cStkSubOpslag:
                    case BBegrotingsRegel.c_cStkEindOpslag:
                        // Type is opslagpost, status geeft aan welke type opslagpost het betreft.
                        type = EOnderbouwing.Opslagpost;
                        break; // '%', '>', '^' of '@'

                    case BBegrotingsRegel.c_cStkCommentaar:
                        type = EOnderbouwing.Commentaar;
                        break; // '"'
                    case BBegrotingsRegel.c_cAlleenOmsHoev:
                    case BBegrotingsRegel.c_cAlleenTotPrys:
                    case BBegrotingsRegel.c_cStkNietafdrukken:
                        // type wordt niet gewijzigd alleen status verandert
                        // '-' tijdelijke waarde, wordt omgezet in status PASSIEF, NIET AFDRUKKEN
                        break;
                    default:
                        {
                            // Een type blijft over:
                            type = EOnderbouwing.Element;

                            // Is het wel een mogelijke stuurcode van een element?
                            if (!stuurcode.TryToInt(out int _))
                                return false;

                            break;
                        }
                }
            }
            return true;
        }

