        /// <summary>
        /// Wijzig de middelcode van een kostenpost
        /// </summary>
        /// <param name="kostenpost">De kostenpost waarvan de middelcode/calculatiecode moet wijzigen</param>
        /// <param name="midcde">De nieuwe middelcode</param>
        /// <param name="rekenen">true: de begroting moet opnieuw worden doorgerekend</param>
        /// <returns>true: de middelcode van de kostenpost is gewijzigd</returns>
        public BOpdracht? WijzigMidCde(BKostenpost kostenpost, string? midcde, out bool rekenen)
        {
            rekenen = false;
            if (_VttId == kostenpost._Id && _Umc)
                return null;

            int stuIndex = _Stu.ZoekKostenpost(kostenpost._Id);
            BWijzigMiddelCode opdracht = new BWijzigMiddelCode(stuIndex, midcde);
            if (!Uitvoeren(opdracht))
