        public void VerwijderenVastPrijsIndicatie()
        {
            // De elementen met vastprijs-indicatie ophalen uit de begroting.
            IList<IBegrotingsRegel> elementen = _Stu.GeefBgrRegels((int)EOnderbouwing.Element);
            List<IBegrotingsRegel> vastprijsElementen = elementen.Where(item => ((BElement)item)._VastPrijs).ToList();

            // Vastprijs-indicatie van het element afhalen, zodat die automatisch wordt doorgerekend.
