            DataTable? cloudDataCache = HaalAlleOnderhoudsGegevensUitDeCloud(eigenschappen?._KostenbestandId);

            // Rekenen Mjob Bedrag gaat vanaf het root element.
            int index = 0;
            _MjobContanteWaardeIsActueel = true;
            RekenenMjobContanteWaardeInvesteringOnderbouwing(_REl, cloudDataCache, ref index);

            if (nieuweGroepeerOpdrachtGemaakt)
            {
                GroepeerOpdrachten(_ViewNr, ProjectResources.TradC115);
