                    if (!string.IsNullOrEmpty(scenario))
                    {
                        WijzigStringBgrRegel(true, stuIndex, BBegrotingsRegel.EGegeven.Scenario, BScenario.ScenarioStatusActueel(scenario), null, out bool lokaal);
