                        }
                        break;
                }
            }
        }

        private bool ControleerUurloon(BUurloonBVzl ulnbVzl, BElement elm, out BUurloonC? ulc)
        {
            bool returnValue = true;
            ulc = null;
            foreach (BUurloonC item in elm._Uln._Vzl)
            {
                if (!ulnbVzl.HeeftUurloon(item._UlnCde))
                {
                    ulc = item;
                    returnValue = false;
                }
            }
            return returnValue;
        }

        private int ControleerHierarchie()
        {
            LogboekMelding(ProjectResources.TradA0024113);
            int gewijzigd = 0;

            List<int> aParents = new(20);

            for (int teller = 0; teller < aParents.Capacity; teller++)
                aParents.Add(-1);

            BStructuurRegel stuRegel;
            _voortgangsBalk.ZetAantalenMsg(0, _Stu._Aantal, ProjectResources.TradA0024114, false, 0);

            for (int stuIndex = 0; stuIndex < _Stu._Aantal; stuIndex++)
            {
                _voortgangsBalk.Perc(stuIndex);
                stuRegel = _Stu[stuIndex];
                switch (stuRegel._Tpe)
                {
                    case EOnderbouwing.Element:
                        if (stuRegel._Niveau != -1)
                            aParents[stuRegel._Niveau] = stuRegel._Id;
                        if (stuRegel._Niveau > 0)
                        {
                            // Restant weer op -1 zetten
                            for (int nivo = stuRegel._Niveau + 1; nivo < aParents.Capacity; nivo++)
                                aParents[nivo] = -1;

                            if (aParents.Contains(stuRegel._PrtId) == false)
                            {
                                LogboekMelding(string.Format(ProjectResources.TradA0024115,
                                   _Stu[stuIndex]._Id, stuIndex, _Stu[stuIndex]._PrtId));

                                gewijzigd = 64 + 1024;
                            }
                        }
                        break;

                    default:
                        if (stuRegel._Niveau > 0)
                        {
                            if (aParents.Contains(stuRegel._PrtId) == false)
                            {
                                LogboekMelding(string.Format(ProjectResources.TradA0024116,
                                   _Stu[stuIndex]._Id, stuIndex, _Stu[stuIndex]._PrtId));

                                gewijzigd = 64 + 1024;
                            }
                        }
                        break;
                }
            }
            return gewijzigd;
        }

