        /// <summary>
        /// Verplaats een regel in de onderbouwing van een element
        /// </summary>
        /// <param name="stuIndex">Index in de structuurlijst van de begrotingsregel die verplaatst moet worden</param>
        /// <param name="naarVoren">true: verplaats de regel naar voren - indien mogelijk</param>
        /// <returns>true indien er een verplaatsing heeft plaatsgevonden</returns>
        public bool VerplaatsOnderbouwing(int stuIndex, bool naarVoren, EViewKey viewNr, bool alsElement)
        {
            int stuIndexDoel;
            int startIndex;
            int count;
            // Bepaal welke regels verplaatst moeten worden en
            // waarheen de selectie verplaatst moet worden
            if (naarVoren)
            {
                int eindeSelectie = _Stu.EindeOnderbouwing(stuIndex) + 1;
                startIndex = stuIndex;
                count = eindeSelectie-startIndex;
                if (alsElement)
                {
                    if (!_Stu.GeefVorigSubElement(stuIndex, out stuIndexDoel))
                        return false;
                }
                else
                {
                    if (!_Stu.GeefVorigeOnderbouwing(stuIndex, out stuIndexDoel))
                        return false;
                }
            }
            else
            {
                int bStuIndex;
                if (alsElement)
                {
                    if (!_Stu.GeefVolgendSubElement(stuIndex, out bStuIndex))
                        return false;
                }
                else
                {
                    if (!_Stu.GeefVolgendeOnderbouwing(stuIndex, out bStuIndex))
                        return false;
                }

                int eindeSelectie = _Stu.EindeOnderbouwing(bStuIndex) + 1;
                startIndex = bStuIndex;
                count = eindeSelectie - startIndex;
                stuIndexDoel = stuIndex;
            }
            int prtId = _Stu[stuIndex]._PrtId;

            // Geef opdracht tot verplaatsing door VerplaatsBegrotingsRegelsSequentieel // bug 3592
            BOpdracht? opdracht = VerplaatsBegrotingsRegelsSequentieel(startIndex, count, stuIndexDoel, prtId);
            if (opdracht == null)
                return false;

            _Context = opdracht._Context;
            opdracht.SetView(viewNr);
            return true;
        }
