        public BOpdracht? WijzigNiveauBgrRegel(BSelectie selectie, bool hoger)
        {
            BOpdracht opdracht;
            if (hoger)
            {
                BVerhoogNiveauBgrRegel verhoogNiveauOpdracht = new BVerhoogNiveauBgrRegel(selectie);
                if (selectie.GeefAantal() <= 1)
                    verhoogNiveauOpdracht.VerhoogNiveau = _optieNiveauWisseling.IsMeedegraderenGewenst();
                opdracht = verhoogNiveauOpdracht;
            }
            else
            {
                opdracht = new BVerlaagNiveauBgrRegel(selectie);
            }

            if (!opdracht.Uitvoeren(this))
                return null;

            MoetRekenen = true;     // herberekening is noodzakelijk
            if (!m_Snel)
            {
                Rekenen(ERekendiepte.Wijzigingen);
                if (opdracht != null)
                    _OpdrachtVzl.Aanmelden(opdracht);
            }
            if (opdracht != null)
                _Context = opdracht._Context;
            return opdracht;
        }

