        public bool Uitvoeren(BWijzigVttId opdracht)
        {
            int vttIdOud = _VttId;
            if (vttIdOud == 0 && opdracht._VttIndexNieuw == 0)
                return false;

            int vttIdNieuw = 0;
            BKostenpost? kostenpostNieuw = null;
            if (opdracht._VttIndexNieuw > 0)
            {
                _Stu.LeesBegrotingsRegel(opdracht._VttIndexNieuw);
                BStructuurRegel stuRegel = _Stu[opdracht._VttIndexNieuw];
                if (stuRegel._Tpe != EOnderbouwing.Kostenpost ||
                   (vttIdOud > 0 && stuRegel._Id == vttIdOud))
                    return false;

                vttIdNieuw = stuRegel._Id;
                kostenpostNieuw = stuRegel._Regel as BKostenpost;
            }

            if (vttIdOud != 0)
            {
                opdracht._VttIndexOud = _Stu.ZoekKostenpost(vttIdOud);      // tbv UNDO

                //    De vorige kostenpost die gebruikt werd om naar een vast totaal toe te
                //    rekenen moet weer een reguliere kostenpost worden.
                // -> Is nu anders:
                // De vorige kostenpost die gebruikt werd om naar een vast totaal toe te
                // rekenen moet een passieve kostenpost worden.
                _Stu.LeesBegrotingsRegel(opdracht._VttIndexOud);
                BStructuurRegel stuRegel = _Stu[opdracht._VttIndexOud];
                BKostenpost? kostenpostOud = stuRegel._Regel as BKostenpost;
                if (kostenpostOud?._Id == _VttId)
                {
                    opdracht._VttOud_Stt = kostenpostOud._Stt;
                    opdracht._VttOud_Dri = kostenpostOud._Dri;

                    // EDri dri = (m_Tpe == EBgrTpe.Elementen) ? EDri.Drn : EDri.Tgd;
                    // kostenpostOud.WijzigDri(dri);
                    kostenpostOud.WijzigDri(EDri.Drn);
                    kostenpostOud._Actief = false;

                }
            }

            VasttotaalId = vttIdNieuw;        // kan 0 zijn

            if (kostenpostNieuw != null)
            {
                opdracht.KostenpostOpslaan(kostenpostNieuw);
                kostenpostNieuw.WijzigRegelStatus(ERegelStatus.Normaal);
                // Nieuw middel aanmaken, aan kostenpost koppelen en in de middelenlijst opnemen
                VerwijderKtpMiddel(kostenpostNieuw, true);
                if (kostenpostNieuw._HeeftProductieFactor)
                {
                    kostenpostNieuw.ZetProductieFactorUit();
                }
                BMiddel middel = new BMiddel(GeefNieuwId(), _VltId);
                middel.MiddelGewijzigd += MiddelGewijzigd;
                middel._Oms = kostenpostNieuw._Middel._Oms;
                middel._Enh = kostenpostNieuw._Middel._Enh;
                kostenpostNieuw.MaakVttKostenpost(middel);
                _Mid.MiddelToevoegen(middel);
                kostenpostNieuw._Actief = true;
            }
            return true;
        }
