        public bool Uitvoeren(BWijzigUmc opdracht)
        {
            if (opdracht.Umc == _Umc)
                return false;                        // Geen wijziging

            if (opdracht.Umc)
            {
                List<string>? dubbeleCodes = opdracht.DubbeleCodes;
                var result = _Mid.UniekGecodeerd(out dubbeleCodes, 0, out _);
                opdracht.DubbeleCodes = dubbeleCodes;

                if (!result) return false;
            }
            else
            {
                opdracht.Middelen = new Hashtable();
                int stuIndex = -1;
                BKostenpost? ktp = (BKostenpost?)_Stu.GeefVolgendeBgrRegel(EOnderbouwing.Kostenpost, ref stuIndex);
                while (ktp != null)
                {
                    BMiddel middel = ktp._Middel;
                    if (!string.IsNullOrEmpty(middel._MidCde))
                    {
                        if (opdracht.Middelen.Contains(middel._Id))
                        {
                            // duplicaat Middel aanmaken
                            var duplMiddel = new BMiddel(GeefNieuwId(), middel, middel._VltId);
                            duplMiddel.MiddelGewijzigd += MiddelGewijzigd;
                            ktp.WijzigMiddel(duplMiddel, false);   // false: rekenen is niet nodig
                            _Mid.MiddelToevoegen(duplMiddel);
                        }
                        else
                        {
                            opdracht.Middelen.Add(middel._Id, middel);
                        }
                    }
                    ktp = (BKostenpost?)_Stu.GeefVolgendeBgrRegel(EOnderbouwing.Kostenpost, ref stuIndex);
                }
            }

            _Umc_Private = opdracht.Umc;
            return true;
        }
