            if (vttIdNieuw > 0)
            {
                BKostenpost? kostenpost = (BKostenpost?)_Stu.GeefBegrotingsRegel(vttIdNieuw);
                if (kostenpost is not null)
                {
                    VerwijderKtpMiddel(kostenpost, true);   // true: een UNDO-actie
                    middel = opdracht.KostenpostHerstellen(kostenpost);
                    _Mid.MiddelToevoegen(middel);
                    if (opdracht._MstKid != 0)
                    {
                        BMeetstaatKoppeling? mk = ZoekMeetstaatKoppeling(opdracht._MstKid);
                        if (mk != null)
                        {
                            kostenpost.MeetstaatKoppeling(mk);
                            if (opdracht._MstKid < 0)
                                kostenpost.MeetstaatOverschreven(false);  // false : niet herstellen
                        }
                    }
                }
            }

            int vttIdOud = 0;
            if (opdracht._VttIndexOud > 0)
            {
                _Stu.LeesBegrotingsRegel(opdracht._VttIndexOud);
                BStructuurRegel stuRegel = _Stu[opdracht._VttIndexOud];
                vttIdOud = stuRegel._Id;
                BKostenpost? kostenpostOud = stuRegel._Regel as BKostenpost;
                kostenpostOud?.StatusHerstellen(opdracht._VttOud_Stt);
                kostenpostOud?.WijzigDri(opdracht._VttOud_Dri);

                kostenpostOud?.MaakVttKostenpost(kostenpostOud._Middel);
            }
            VasttotaalId = vttIdOud;
            opdracht._RegelNummer = opdracht._VttIndexNieuw;
