        public EBimMeetstaatKoppelVersie GeefBimKoppelVersie()
        {
            EBimMeetstaatKoppelVersie bimKoppelVersie = EBimMeetstaatKoppelVersie.Onbekend;

            if (m_Metingen != null)
            {
                List<BStructuurRegel> metingRegels = (from BStructuurRegel rgl in _Stu.Lijst
                                                      where rgl._Regel?._Meting != null &&
                                                            rgl._Regel?._MetingProvider == EMetingProvider.BimOnline
                                                      select rgl).ToList();

                if (metingRegels.Count > 0)
                {
                    bool idKoppeling = (from BStructuurRegel rgl in metingRegels
                                        where rgl._Regel?._Meting?._MtnGuid == Guid.Empty
                                        select rgl).Any();

                    bool guidKoppeling = (from BStructuurRegel rgl in metingRegels
                                          where rgl._Regel?._Meting?._MtnGuid != Guid.Empty
                                          select rgl).Any();

                    if (idKoppeling) bimKoppelVersie |= EBimMeetstaatKoppelVersie.Id;
                    if (guidKoppeling) bimKoppelVersie |= EBimMeetstaatKoppelVersie.Guid;

                    Debug.Assert(bimKoppelVersie != EBimMeetstaatKoppelVersie.Combinatie, "Ongeldige combinatie van bim metingen oude en nieuwe stijl");//NIETVERTALEN
                }

            }
            return bimKoppelVersie;
        }

