        public bool Uitvoeren(BVervangMiddel vervangOpdracht)
        {
            if (m_Stu == null ||
                _Stu._Aantal <= vervangOpdracht.StuIndexDoel ||
                vervangOpdracht.StuIndexDoel <= 0 ||
                vervangOpdracht.MiddelOrig == null)
                return false;

            var kostenpostDoel = _Stu[vervangOpdracht.StuIndexDoel]._Regel as BKostenpost;
            if (kostenpostDoel == null)
                return false;

            // Wijzigt de code van het middel?
            string nieuweCode = vervangOpdracht.MiddelOrig._MidCde;
            if (string.Compare(nieuweCode, kostenpostDoel._CclCde, StringComparison.Ordinal) != 0)
                vervangOpdracht.WijzigCodeOpdracht = new BWijzigMiddelCode(vervangOpdracht.StuIndexDoel, nieuweCode);

            if (_Umc && vervangOpdracht.Controlevraag != null)
            {
                BMiddel? middel = _Mid.ZoekMidCde(nieuweCode, out bool verwijderd);  // Ga na of de nieuwe code al voorkomt in de doelbegroting
                if (middel != null && !verwijderd)
                {
                    int aantalKostenposten = _Stu.AantalKostenpostenVanMiddel(middel._Id);
                    bool inclActieveRegel = vervangOpdracht.WijzigCodeOpdracht == null;  // De code van de actieve regel komt al overeen met de nieuwe middelcode
                    if (!vervangOpdracht.Controlevraag(nieuweCode, aantalKostenposten, inclActieveRegel))  // false: annuleren
                        return false;
                }
            }
            if (vervangOpdracht.WijzigCodeOpdracht != null && !Uitvoeren(vervangOpdracht.WijzigCodeOpdracht))
                return false;

            // Maak een kopie van het ongewijzigde middel ten behoeve van het ongedaan maken
            BMiddel middelDoel = kostenpostDoel._Middel;
            BMiddel middelOud = new BMiddel(middelDoel._Id, middelDoel._VltId);
            middelOud.GegevensOvernemen(middelDoel);
            vervangOpdracht.MiddelOud = middelOud;
            vervangOpdracht.MiddelDoel = middelDoel;

            // Neem ook de overige gegevens over, incl. de wzgdtm
            middelDoel.GegevensOvernemen(vervangOpdracht.MiddelOrig);

            // Neem ook de valuta over
            middelDoel._VltId = BDocValuta.GeefValutaId(vervangOpdracht._bgrOrig.BegrotingsValuta, BegrotingsValuta, vervangOpdracht.MiddelOrig._VltId);

            middelDoel.WijzigingInMiddel();
            kostenpostDoel.BgrRglGewijzigd(true);

            _Context = vervangOpdracht._Context;

            return true;
        }
