                foreach (int stuIndex in opdracht.StuIndexLijst)
                {
                    IBegrotingsRegel? bgrRegel = _Stu[stuIndex]._Regel;
                    bgrRegel?._NieuwePagina = false;
                }
            }
            return opdracht.StuIndexLijst.Count > 0;
        }
