        public void OngedaanMaken(BWijzigMiddelCode opdracht)
        {
            //opdracht._RegelNummer = opdracht.m_StuIndex-1;
            opdracht._RegelNummer = opdracht.StuIndex;
            _Context = opdracht._Context;
            BKostenpost? kostenpost = _Stu[opdracht.StuIndex]._Regel as BKostenpost;

            if (!_Umc)                                                   // geen unieke middelencodering?
            {
                // elke kostenpost z'n eigen middel:
                // dit heeft geen consequenties voor andere kostenposten
                kostenpost?._Middel.WijzigMiddelCode(opdracht.MidCdeOud);
                kostenpost?.MiddelGewijzigd(false);                       // false: geen herberekening nodig
            }
            else
            {
                if (opdracht.MeerKtpOud)           // Meerdere kostenposten pasten het middel met de oude code toe
                {
                    if (opdracht.MeerKtpNieuw)      // Nieuwe middelcode werd reeds toegepast
                    {
                        // - Als #KTP_OUD > 1 en #KTP_NIEUW > 1 dan wijzigde alleen de koppeling tussen kostenpost en middel.
                        kostenpost?.WijzigMiddel(opdracht.MiddelOud, true);            // true: rekenen
                    }
                    else                             // Nieuwe code kwam nog niet voor (of was leeg)
                    {
                        // - Als #KTP_OUD > 1 en #KTP_NIEUW = 1 dan moest een kopie van het oude middel worden gemaakt.
                        BMiddel? middelNieuw = kostenpost?._Middel;
                        kostenpost?.WijzigMiddel(opdracht.MiddelOud, true);            // true: rekenen
                        _Mid.MiddelVerwijderen(middelNieuw, true);  // true: een UNDO-actie
                    }
                }
                else     // Slechts 1 kostenpost die het middel met de huidige code toepast
                {
                    if (opdracht.MeerKtpNieuw)      // Nieuwe middelcode werd reeds toegepast
                    {
                        // - Als #KTP_OUD = 1 en #KTP_NIEUW > 1 dan moest het oude middel worden verwijderd.
                        _Mid.MiddelVerwijderenOngedaanMaken(1);
                        kostenpost?.WijzigMiddel(opdracht.MiddelOud, true);            // true: rekenen
                    }
                    else                             // Nieuwe code kwam nog niet voor (of was leeg)
                    {
                        // - Als #KTP_OUD = 1 en #KTP_NIEUW = 1 dan wijzigde alleen de middelcode van het middel.
                        kostenpost?._Middel.WijzigMiddelCode(opdracht.MidCdeOud);
                        kostenpost?.MiddelGewijzigd(false);  // false: geen herberekening nodig
                    }
                    if (opdracht.UurloonToegevoegd)
                    {
                        // Verwijder overbodig geworden uurloon
                        BUurloonBVzl ulnVzl = (BUurloonBVzl)_REl._Uln;
                        ulnVzl.Verwijderen(1);
                    }
                }
                BMiddel? mid = GeefMiddel(opdracht.MidCdeNieuw);
                if (mid != null)
                {
                    if (_Mid.GeefMiddelenGebruikOpId(mid._Id, forceren: true).Count == 0)
                        _Mid.MiddelVerwijderen(mid, true);
                }
            }
            if (!opdracht.GeenWijzigDatum && kostenpost is { } kp)
                kp._Middel._WzgDtm = opdracht.WijzigDatum;
        }

