            BKostenpost? kostenpost = (BKostenpost?)bgrStructuur.GeefVolgendeBgrRegel(EOnderbouwing.Kostenpost, ref stuIndex);
            while (kostenpost != null)
            {
                if (kostenpost._Actief && kostenpost._Middel._Id == middelId)
                {
                    if (kostenpost._Dri != EDri.Tgd)
                        cumulatieveHvh += kostenpost._DrkHvh;
