        /// <summary>get/set Bgv Property: Begrotingsblad werkt met begrotingsposten 
        /// </summary>
        public bool BegrotingspostenToepassen
        {
            get
            {
                BBegrotingsGegeven? bgv = _Bgv.GeefBegrotingsGegeven(BBegrotingsGegeven.c_bbdbgrpst);
                if (bgv != null)
                    return bgv._Wde.Length > 0 && bgv._Wde[0] == 'J';

                BegrotingspostenToepassen = false;
                return false;
            }
            set
            {
                BBegrotingsGegeven bgv = _Bgv.MaakBegrotingsGegeven(BBegrotingsGegeven.c_bbdbgrpst, EGgvTpe.Tekst, "BgrBlad heeft BgrPosten");//NIETVERTALEN
                bgv._Wde = value ? "J" : "N";//NIETVERTALEN
                if (m_Bbd != null && m_Bbd._BgrPostToepassen != value)
                {
                    m_Bbd._BgrPostToepassen = value;

                    if (_BrinkKostenbestandEigenschappenOnderhoud?._MJOBActiefBerekenen == true)
                    {
                        // Direct de regel berekenen.
                        RekenenMjobContanteWaardeInvestering();
                    }
                    else
                    {
                        // Parameter op false zetten.
                        _MjobContanteWaardeIsActueel = false;
                    }
                }
            }
        }

        public bool _KanBgrPostDoorrekenen => (_Tpe == EBgrTpe.Traditioneel || _Tpe == EBgrTpe.Raw) && BegrotingspostenToepassen;

