            // Is het een bestaand gebruikersgegeven?
            BGebruikersGegeven? gebruikersGegeven = _Ggv.GeefGebruikersGegeven(naam);
            if (gebruikersGegeven != null &&
               gebruikersGegeven._Wde != waarde)
