        private void ControleerElement()
        {
            if (!_structuurStatusFout.Uitvoeren(EBegrotingControleStap.Elementen))
                return;

            LogboekMelding(ProjectResources.TradA002419);

            _voortgangsBalk.ZetAantalenMsg(0, _Stu._Aantal, ProjectResources.TradA002419, false, 0);
            BUurloonBVzl ulnbVzl = GeefUurloonBVzl();

            for (int stuIndex = 1; stuIndex < _Stu._Aantal; stuIndex++)
            {
                _voortgangsBalk.Perc(stuIndex);
                switch (_Stu[stuIndex]._Tpe)
                {
                    case EOnderbouwing.Element:
                        int elementId = _Stu[stuIndex]._Id;
                        BElement? element = _Stu[stuIndex]._Regel as BElement;
                        if (element != null && !ControleerUurloon(ulnbVzl, element, out _))
                        {
                            element._Uln.Opschonen();
                            element.ZetMutatieStatus(BewaarItemMutatieStatus.Gewijzigd);
                            _OpdrachtVzl.Gewijzigd();
                            LogboekMelding(string.Format(ProjectResources.TradA0024110 + BStatics.c_Spatie,/*//NIETVERTALEN*/
                                     elementId, stuIndex));
                            _structuurStatusFout.VoegStatusToe(EStructuurStatusFout.Uurloon);
                        }

                        for (int zoekIndex = 1; zoekIndex < _Stu._Aantal; zoekIndex++)
                        {
                            if (zoekIndex != stuIndex &&
                               _Stu[zoekIndex]._Tpe == EOnderbouwing.Element &&
                               _Stu[zoekIndex]._Id == _Stu[stuIndex]._Id)
                            {
                                if (_structuurStatusFout.ControleerBegrotingStatus == EControleerBegrotingStatus.ControlerenEnRepareren)
                                {
                                    IBegrotingsRegel? nieuwElement = MaakNieuwElement(stuIndex);
                                    LogboekMelding(string.Format(ProjectResources.TradA0024111,
                                        elementId, stuIndex, _Stu[zoekIndex]._Tpe, _Stu[zoekIndex]._Id, zoekIndex, nieuwElement?._Id));
                                }
                                else
                                {
                                    LogboekMelding(string.Format(ProjectResources.TradA0024112,
                                       elementId, stuIndex, _Stu[zoekIndex]._Tpe, _Stu[zoekIndex]._Id));
                                }
                                _structuurStatusFout.VoegStatusToe(EStructuurStatusFout.Element);
                            }
                        }
                        break;
                }
            }
        }

        private bool ControleerUurloon(BUurloonBVzl ulnbVzl, BElement elm, out BUurloonC? ulc)
        {
            bool returnValue = true;
            ulc = null;
            foreach (BUurloonC item in elm._Uln._Vzl)
            {
                if (!ulnbVzl.HeeftUurloon(item._UlnCde))
                {
                    ulc = item;
                    returnValue = false;
                }
            }
            return returnValue;
        }

