        /// <summary>Filter een begroting op bestaande regels in een andere begroting op basis van een code
        /// <para>Voorlopig alleen op calculatie code mogelijk</para>
        /// <para>NB Dit werkt dus niet met lege codes</para>
        /// </summary>
        /// <param name="doelBegroting">De begroting waarvan getest wordt of de code daar al in voorkomt</param>
        /// <param name="inclusiefBovenBouw"></param>
        /// <param name="inclusiefOnderbouwing"></param>
        /// <param name="stuIndexDoel">Een nieuwe locatie waar het 'ovegebleven" deel van deze begroting geplakt kan worden</param>
        /// <returns>true indien er regels uitgefilter zijn, anders false</returns>
        public bool KbFilterClassificatieRegels(IBegroting doelBegroting, IList<IKostenbestandRaadplegenItem> brinkKbRegels, ref int stuIndexDoel)
        {
            int stuIndex = 1; // NB lijst heeft geen root element m_Stu wel >> stuIndex begint met 1
            int niveau = 1;
            int zoekVanafIndex = 0;
            bool regelsGefilterd = false, heeftLegeClassificatieCodes = false;

            foreach (object item in brinkKbRegels)
            {
                BKlasse? itemCla = item as BKlasse;
                if (itemCla != null && string.IsNullOrEmpty(itemCla.code))
                {
                    heeftLegeClassificatieCodes = true;
                    break;
                }
            }

            // Als er lege classificatie codes gevonden worden dan werkt het hele mechanisme 
            // van classificatie codes opzoeken niet meer en valt het hele systeem om
            if (heeftLegeClassificatieCodes)
                return false;

            foreach (object item in brinkKbRegels)
            {
                BKlasse? itemCla = item as BKlasse;
                if (itemCla != null && !string.IsNullOrEmpty(itemCla.code))
                {
                    int gevondenIndex = doelBegroting.ZoekElementCodeVanNiveau(itemCla.code, zoekVanafIndex, niveau);
                    if (gevondenIndex > 0)
                    {
                        _Stu[stuIndex]._Niveau = -_Stu[stuIndex]._Niveau;
                        stuIndexDoel = zoekVanafIndex = gevondenIndex;
                        regelsGefilterd = true;
                    }
                    niveau++;
                }
                stuIndex++;
            }

            return regelsGefilterd;
        }
        /// <summary>Bepaal de invoeglocatie voor een aantak kbRegels.
        /// <para>Hierbij wordt de instelling voor Element en Activiteit niveau gevolgd</para>
        /// <para>NB Dit is alleen van toepassing op kbRegel verzamelingen zonder bovenbouw (classificaties)
        /// Zodra die regels in de verzameling aanwezig zijn wordt de hierarchie van de classificaties gevolgd</para>
        /// </summary>
        /// <param name="huidigeStuIndex"></param>
        /// <param name="kbRegels"></param>
        /// <returns></returns>
        public int KbBepaalInvoegLocatie(int huidigeStuIndex, IList<IKostenbestandRaadplegenItem> kbRegels)
        {
            int stuIndex = huidigeStuIndex;
            int invoegNiveau = 0;

            BBrinkKostenbestandEigenschappen kbEigenschappen = new BBrinkKostenbestandEigenschappen(_KostenbestandEigenschappenNieuwbouw);
