        /// <returns>true indien het onderbouwingstype is gewijzigd</returns>
        public BOpdracht? OmzettenBegrotingsRegel(int stuIndex, EOnderbouwing naarType, bool klassiek)
        {
            Debug.Assert(m_Stu != null, "Geen structuurlijst in de begroting");
            Debug.Assert(stuIndex >= 0, "Verkeerde structuurlijstindex: te laag");
            Debug.Assert(stuIndex < _Stu._Aantal, "Verkeerde structuurlijstindex: te hoog");

