        /// <summary>Bereken voor iedere valuta (ook de basivaluta) het gebruik 
        /// NB Deze method berekent het valutagebruik over alle regels. Er wordt (nog) geen rekening gehouden met selecties
        /// </summary>
        public void BerekenValutaGebruik()
        {
            m_BasisValuta!.NettoTotaal = m_BasisValuta.BrutoTotaal = 0.0;
            foreach (BValutaDeco valuta in BegrotingsValuta)
            {
                valuta.NettoTotaal = valuta.BrutoTotaal = 0.0;
            }

            for (int stuIndex = 0; stuIndex < _Stu._Aantal; stuIndex++)
            {
                BStructuurRegel stuRegel = _Stu[stuIndex];
                if (stuRegel._Tpe == EOnderbouwing.Kostenpost)
                {
                    BKostenpost kp = (BKostenpost)_Stu.GeefBegrotingsRegel(stuRegel);
                    if (kp._Actief)
                    {
                        BValutaDeco valuta = GeefValutaMetId(kp._Middel._VltId);
                        BXtoKst xto = kp.GeefBedragen();
                        double uurtarief = kp.Begroting.GeefUurTarief(kp._Middel._UlnCde).Waarde;
                        double arbeid = kp._Middel._UurNrm * uurtarief;
                        double bedragen = kp._Middel._PrsMta + kp._Middel._PrsMte + kp._Middel._PrsOda;
                        double valutaBedrag = (bedragen + arbeid) * kp._DrkHvh;
                        valuta.NettoTotaal += valutaBedrag;
                        valuta.BrutoTotaal += valutaBedrag * valuta.KoersFactor;
                    }
                }
            }
        }
