                        }

                        for (int zoekIndex = 1; zoekIndex < _Stu._Aantal; zoekIndex++)
                        {
                            if (zoekIndex != stuIndex &&
                               _Stu[zoekIndex]._Tpe == EOnderbouwing.Element &&
                               _Stu[zoekIndex]._Id == _Stu[stuIndex]._Id)
                            {
