        /// <param name="omschrijving">Omschrijving van de meetstaat (die anders uit de begrotingsregel komt)</param>
        /// <param name="opmaakNaam">Naam van de voor deze meetstaat laatst gebruikte opmaak</param>
        /// <returns>De nieuwe meetstaat</returns>
        public BMeetstaat CnvMeetstaatToevoegen(BMeetstaatModel model, string omschrijving, string opmaakNaam)
        {
            // Maak de meetstaat
            BMeetstaat meetstaat = new BMeetstaat(model, true);  // true: nieuwe meetstaat
            meetstaat._Id = GeefNieuwId();
            meetstaat.WijzigOmschrijving(omschrijving);
            meetstaat.WijzigOpmaak(opmaakNaam);
            meetstaat.Begroting = this;

            // Voeg de meetstaat toe aan de lijst
            _Meetstaten.Add(meetstaat);

            return meetstaat;
        }

        public bool MeetstaatKoppelen(IMeetstaat meetstaat, int stuIndex)
        {
            if (meetstaat._Model == null) return false;

            int sgkId = meetstaat._Model._StandaardGekoppeldeKolomId;
            var koppeling =
               new BMeetstaatKoppeling(BewaarItemMutatieStatus.Nieuw, meetstaat._Id, sgkId, BMeetstaatRegel.c_TotaalRegelId);

            return MeetstaatKoppelen(meetstaat, stuIndex, koppeling);
        }

        public bool MeetstaatKoppelen(int kolomNr, int regelNr, IMeetstaat meetstaat, int stuIndex)
        {
            // Als er geen kolom- ?n geen regelnummer bekend is dan wordt het een standaardkoppeling
            if (kolomNr < 0 && regelNr < 0)
                return MeetstaatKoppelen(meetstaat, stuIndex);

            // Maak de koppeling
            BMeetstaatKoppeling? koppeling = meetstaat.MaakKoppeling(kolomNr, regelNr);

            return MeetstaatKoppelen(meetstaat, stuIndex, koppeling!);
        }

        private bool MeetstaatKoppelen(IMeetstaat meetstaat, int stuIndex, BMeetstaatKoppeling koppeling)
        {
            // Controleer de begrotingsregel
            IBegrotingsRegel? bgrRegel = _Stu[stuIndex]._Regel;
            if (bgrRegel?._Koppelbaar != true)
                return false;

            Debug.Assert(koppeling._Nieuw, "MeetstaatKoppelen() - nieuw id maar geen nieuwe koppeling");
            koppeling._KoppelingId = GeefNieuwId();

            var opdracht = new MeetstaatKoppelenOpdracht(this, meetstaat, stuIndex, koppeling)
            {
                _ViewNr = _ViewNr
            };
            return _OpdrachtVzl.Uitvoeren(opdracht);
        }

