        public bool GebruiktUurloon(string uurlooncode)
        {
            int stuIndex = 0;
            while (stuIndex < _Stu._Aantal)
            {
                // Zorg dat de begrotingsregel gelezen is
                _Stu.LeesBegrotingsRegel(stuIndex);
                BStructuurRegel stuRegel = _Stu[stuIndex];
                if (stuRegel._Regel?._OnderbouwingType == EOnderbouwing.Kostenpost)
                {
                    BKostenpost kp = (BKostenpost)stuRegel._Regel;
                    if (kp._UlnCde == uurlooncode)
                        return true;
                }
                stuIndex++;
            }


            return false;
        }
