    /// <param name="fcowPerc">Fco percentage (default 0.15)</param>
    /// <param name="rawMax">Maximale Raw bijdrage (default 75000)</param>
    /// <param name="fcowMax">Maximale Fco bijdrage (default 75000)</param>
    public void ZetRawWaarden(double rawPerc, double fcowPerc, double vsiPerc, double rawMax, double fcowMax, double vsiMax)
    {
        _RawPercentage = rawPerc;
        _FcoPercentage = fcowPerc;
        _VsiPercentage = vsiPerc;
