        {
            case ERawGegeven.GedaanTe: sleutel = c_RawGedaanTe; break;
            case ERawGegeven.GedaanDatum: sleutel = c_RawGedaanDatum; break;
            case ERawGegeven.Inschrijver1: sleutel = c_RawInschrijver1; break;
            case ERawGegeven.Inschrijver2: sleutel = c_RawInschrijver2; break;
            case ERawGegeven.Inschrijver3: sleutel = c_RawInschrijver3; break;
            case ERawGegeven.Inschrijver4: sleutel = c_RawInschrijver4; break;
            case ERawGegeven.BestekNummer: sleutel = c_BestekNummer; break;
            case ERawGegeven.BestekOmschrijving: sleutel = c_BestekOmschrijving; break;
            case ERawGegeven.ContractDatum: sleutel = c_ContractDatum; break;
            case ERawGegeven.ContractDatumGew: sleutel = c_ContractDatumGew; break;
            case ERawGegeven.RegistratieDatum: sleutel = c_RegistratieDatum; break;
            case ERawGegeven.RegistratieNummer: sleutel = c_RegistratieNummer; break;
            case ERawGegeven.CodeLicentieHouder: sleutel = c_CodeLicentieHouder; break;
            case ERawGegeven.OvkNummer: sleutel = c_OvkNummer; break;
            case ERawGegeven.Contractvorm: sleutel = c_Contractvorm; break;
            case ERawGegeven.Jaarversie: sleutel = c_Jaarversie; break;

        }
        if (!string.IsNullOrEmpty(sleutel))
