        /// </summary>
        /// <param name="stuIndex">Index van structuurelement behorend bij de begrotingsregel</param>
        /// <param name="methode">Bepaalt wat er met de onderbouwing van een verwijderd element moet gebeuren</param>
        public BOpdracht VerwijderBegrotingsRegel(int stuIndex, EBgrRegelVerwijderen methode)
