        private void VerwijderMeetstaat(int meetstaatId)
        {
            // Geen controles, er wordt geen opdracht gegenereerd
            IMeetstaat meetstaat;
            for (int index = _Meetstaten.Count - 1; index >= 0; index--)
            {
                meetstaat = _Meetstaten[index];
                if (meetstaat._Id == meetstaatId)
                {
                    _Meetstaten.RemoveAt(index);
                    _Metingen?.VerwijderMeetstaatMetingKoppelingen(meetstaatId);
