        /// <summary>
        /// Per regel uit de begroting het Mjob Bedrag, de contante waarde en investering berekenen.
        /// </summary>
        /// <param name="regel"></param>
        /// <param name="kostenbestandEigenschappen"></param>
        /// <param name="index"></param>
        internal void RekenenMjobContanteWaardeInvestering(IBegrotingsRegel? bgrRegel, DataTable? cloudDataCache)
        {
            if (bgrRegel == null) return;
            bool rekenen;
            bool lokaal;
            bool kostenbestandAanwezig;
            int stuIndex = _Stu.ZoekId(bgrRegel._Id);

            if (bgrRegel._OnderbouwingType == EOnderbouwing.Element || bgrRegel._OnderbouwingType == EOnderbouwing.Kostenpost)
            {
                if (bgrRegel.GeefString(BBegrotingsRegel.EGegeven.OnderhoudsCode, false) != string.Empty)
                {
                    DataTable? cloudData;
                    if (cloudDataCache == null)
                    {
                        BBrinkKostenbestandEigenschappen? eigenschappen = _BrinkKostenbestandEigenschappenOnderhoud;
                        cloudData = HaalOnderhoudsGegevensUitDeCloud(eigenschappen?._KostenbestandId, stuIndex);
                    }
                    else
                    {
                        cloudData = HaalOnderhoudsGegevensUitDeCloudCache(cloudDataCache, stuIndex);
                    }
                    // Checken of er in data uit de cloud handelingen aanwezig zijn, dan venster tonen.
                    // Eerste regel is het onderdeel en geen handeling, dus count > 1.

                    // cloudData geeft altijd wat terug. Ook als er geen Onderdeelcode gevonden is (en dus geen handelingen).
                    // In dat geval is er maar ??n regel waarbij er geen onderhoudscode aanwezig is.
                    // Een handelingcode kan niet leeg zijn.

                    if (cloudData != null && cloudData.Rows.Count >= 1)
                    {
                        bool eersteRegelHeeftHandelingCode = true;
                        BScenario scenario;
                        if (cloudData.Rows.Count == 1)
                        {
                            eersteRegelHeeftHandelingCode = !string.IsNullOrEmpty((string)cloudData.Rows[0]["hndcode"]);///NIETVERTALEN
                        }
                        if (eersteRegelHeeftHandelingCode)
                        {
                            // Op basis van de onderhoudscode de data uit de cloud halen.
                            scenario = new BScenario(bgrRegel, _BrinkKostenbestandEigenschappenOnderhoud);
                            scenario.ZetActueel(m_BrinkKostenbestandEigenschappenOnderhoud?._Wijzigdatum ?? default);
                            scenario.LeesStandaardScenario(cloudData);

                            WijzigDoubleBgrRegel(stuIndex, BBegrotingsRegel.EGegeven.MjobBedrag, scenario.MjobBedrag, false);
                            WijzigDoubleBgrRegel(stuIndex, BBegrotingsRegel.EGegeven.ContanteWaarde, scenario.ContanteWaarde, false);
                            // Investering is het doorgerekend totaal plus de contante waarde van de regel.
                            WijzigDoubleBgrRegel(stuIndex, BBegrotingsRegel.EGegeven.Investering, _afronden.Bedrag(bgrRegel.GeefDouble(BBegrotingsRegel.EGegeven.drktot, out bool geenWaarde) + scenario.ContanteWaarde, 0), false);
                            WijzigStringBgrRegel(true, stuIndex, BBegrotingsRegel.EGegeven.Scenario, scenario.SchrijfScenario(), null, out lokaal);
                        }
                        else
                        {
                            // Geen handelingen.
                            WijzigDoubleBgrRegel(stuIndex, BBegrotingsRegel.EGegeven.MjobBedrag, 0.0, false);
                            WijzigDoubleBgrRegel(stuIndex, BBegrotingsRegel.EGegeven.ContanteWaarde, 0.0, false);
                            WijzigDoubleBgrRegel(stuIndex, BBegrotingsRegel.EGegeven.Investering, bgrRegel.GeefDouble(BBegrotingsRegel.EGegeven.drktot, out rekenen), false);

                            // LETOP! Als er geen kostenbestand is, laten we het scenario intact, anders maken we het scenario leBBegrotingsRegel.EGegeven.
                            kostenbestandAanwezig = (_BrinkKostenbestandEigenschappenOnderhoud?._KostenbestandId != null) && (_BrinkKostenbestandEigenschappenOnderhoud?._KostenbestandId != Guid.Empty);
                            if (kostenbestandAanwezig)
                            {
                                WijzigStringBgrRegel(true, stuIndex, BBegrotingsRegel.EGegeven.Scenario, "", null, out lokaal);//NIETVERTALEN
                            }

                        }
                    }
                    else
                    {
                        // Geen Clouddata.
                        WijzigDoubleBgrRegel(stuIndex, BBegrotingsRegel.EGegeven.MjobBedrag, 0.0, false);
                        WijzigDoubleBgrRegel(stuIndex, BBegrotingsRegel.EGegeven.ContanteWaarde, 0.0, false);
                        WijzigDoubleBgrRegel(stuIndex, BBegrotingsRegel.EGegeven.Investering, bgrRegel.GeefDouble(BBegrotingsRegel.EGegeven.drktot, out rekenen), false);

                        // LETOP! Als er geen kostenbestand is, laten we het scenario intact, anders maken we het scenario leBBegrotingsRegel.EGegeven.
                        kostenbestandAanwezig = (_BrinkKostenbestandEigenschappenOnderhoud?._KostenbestandId != null) && (_BrinkKostenbestandEigenschappenOnderhoud?._KostenbestandId != Guid.Empty);
                        if (kostenbestandAanwezig)
                        {
                            WijzigStringBgrRegel(true, stuIndex, BBegrotingsRegel.EGegeven.Scenario, "", null, out lokaal);//NIETVERTALEN
                        }
                    }

                }
                else
                {
                    // Geen onderhoudscode.
                    WijzigDoubleBgrRegel(stuIndex, BBegrotingsRegel.EGegeven.MjobBedrag, 0.0, false);
                    WijzigDoubleBgrRegel(stuIndex, BBegrotingsRegel.EGegeven.ContanteWaarde, 0.0, false);
                    WijzigDoubleBgrRegel(stuIndex, BBegrotingsRegel.EGegeven.Investering, bgrRegel.GeefDouble(BBegrotingsRegel.EGegeven.drktot, out rekenen), false);
