public sealed class RawContributionCalculator
{
    private readonly RawInfoSettings _settings;

    public RawContributionCalculator(RawInfoSettings settings)
        => _settings = settings;

    public double BepaalBijdrage(double grondBedrag, double opslagFactor, RawCode code)
    {
        var factor = 1.0 - (_settings.RawPercentage + _settings.FcoPercentage + _settings.VsiPercentage);
        if (factor >= 1.0) return grondBedrag * opslagFactor;

        var max = code switch
        {
            RawCode.Raw => _settings.RawMax,
            RawCode.Fco => _settings.FcoMax,
            RawCode.Vsi => _settings.VsiMax,
            _ => double.MaxValue
        };

        return Math.Min(grondBedrag / factor * opslagFactor, max);
    }
}
