    internal bool IsSubtotaal9VanRO(IBegroting begroting, int id)
    {
        bool subtotaal9VanRO = false;
        if (RawIsRaamovereenkomst())
        {
            BElement? parentElement = begroting.GeefParentElement(id, out _);
            subtotaal9VanRO = parentElement._CclCde == "9";
        }
        return subtotaal9VanRO;
    }

    internal void MaakBruto(BBegroting bgr, out bool rawVttIdVerwijderd)
    {
