#15053 RAW begroting opslaan als bruto begroting moet alle 9 posten verwerken en daarna verwijderen
           Op zichzelf is het verwerken van de “9” posten bij opslaan als bruto begroting wel te doen
           Ik loop echter tegen een (onoplosbaar?) probleem aan bij “Herbereken totaal vanuit eenheidsprijs”
           Doordat alle kostenposten en uurlonen met een factor verhoogd worden is het effect van het herberekenen van de totaalprijs vanuit de eenheidsprijs te groot geworden. Hoe groter het bedrag hoe groter de afwijking.
           De enige optie die wellicht zou kunnen werken is: 
           1.    Gevonden situatie uitrekenen
           2.    Opslaan als nieuwe begroting
           3.    Herberekenen totaal …. uitzetten
           4.    9 posten “leegmaken” en rekenen
           5.    Het verschil tussen 1 en 4 is dan volgens mij het “bedrag” dat verdeeld moet worden over de kostenposten.
           Ik wil nog even nadenken of er nog meer problemen zijn bij deze actie
           -      Herbereken totaal vanuit eenheidsprijs
           -      Vastprijs indicatie (volgens mij gaat dit ook bij niet RAW fout)
           -      Productiefactor?
           -      …….
        */
        #endregion Info Discussie WJ/SGB

        rawVttIdVerwijderd = false;
        ERawBeginStaart rawBeginStaart = ERawBeginStaart.Geen;
        BStructuurRegel stuRegel;
        for (int stuIndex = bgr._Stu._Aantal - 1; stuIndex > 0; stuIndex--)
        {
            stuRegel = bgr._Stu[stuIndex];
            ERawBeginStaart type = RawIsBeginRawStaart(stuRegel);
            if (type != ERawBeginStaart.Geen)
            {
                rawBeginStaart |= type;
                if (type == ERawBeginStaart.Code9) break;
                if (rawBeginStaart != ERawBeginStaart.Geen && type == ERawBeginStaart.Geen) break;
            }
        }


        if (rawBeginStaart != ERawBeginStaart.Geen)
        {
            // Er is een Raw hoofdstuk 9 gevonden: Alle elementen hiervan verwijderen
            for (int stuIndex = bgr._Stu._Aantal - 1; stuIndex > 0; stuIndex--)
            {
                stuRegel = bgr._Stu[stuIndex];
                IBegrotingsRegel bgrRegel = stuRegel._Regel;
                if (bgrRegel._Id == bgr._VttId)
                {
                    rawVttIdVerwijderd = true;
                }
                if (stuRegel._Tpe == EOnderbouwing.Element)
                {
                    bgr.VerwijderBegrotingsRegel(stuIndex, EBgrRegelVerwijderen.Onderbouwing);
                }

                // Stop als we Hoofdstuk "9" / "91" gehad hebben
                ERawBeginStaart type = RawIsBeginRawStaart(stuRegel);
                if (type == ERawBeginStaart.Code9)
                {
                    break;
                }
                if (type == ERawBeginStaart.Code91 && ((rawBeginStaart & ERawBeginStaart.Code9) == 0))
                {
                    break;
                }
            }
        }
    }

    public string RawStringGegeven(ERawGegeven gegeven)
    {
        string waarde = string.Empty;
        string sleutel = string.Empty;

        switch (gegeven)
        {
            case ERawGegeven.GedaanTe: sleutel = c_RawGedaanTe; break;
            case ERawGegeven.GedaanDatum: sleutel = c_RawGedaanDatum; break;
            case ERawGegeven.Inschrijver1: sleutel = c_RawInschrijver1; break;
            case ERawGegeven.Inschrijver2: sleutel = c_RawInschrijver2; break;
            case ERawGegeven.Inschrijver3: sleutel = c_RawInschrijver3; break;
            case ERawGegeven.Inschrijver4: sleutel = c_RawInschrijver4; break;
            case ERawGegeven.BestekNummer: sleutel = c_BestekNummer; break;
            case ERawGegeven.BestekOmschrijving: sleutel = c_BestekOmschrijving; break;
            case ERawGegeven.ContractDatum: sleutel = c_ContractDatum; break;
            case ERawGegeven.ContractDatumGew: sleutel = c_ContractDatumGew; break;
            case ERawGegeven.RegistratieDatum: sleutel = c_RegistratieDatum; break;
            case ERawGegeven.RegistratieNummer: sleutel = c_RegistratieNummer; break;
            case ERawGegeven.CodeLicentieHouder: sleutel = c_CodeLicentieHouder; break;
            case ERawGegeven.OvkNummer: sleutel = c_OvkNummer; break;
            case ERawGegeven.Contractvorm: sleutel = c_Contractvorm; break;
            case ERawGegeven.Jaarversie: sleutel = c_Jaarversie; break;

        }
        if (!string.IsNullOrEmpty(sleutel))
        {
            BBegrotingsGegeven? bgv = m_Bgv.GeefBegrotingsGegeven(sleutel);
            if (bgv != null)
                waarde = bgv._Wde;
        }
        return waarde;
    }
