    /// <summary>Geeft aan of een kolom vergeleken kan worden met een (referentie) waarde
    /// Dit wordt o.a. gebruikt om te bepalen of er bij een opmaak een vergelijkkolom gemaakt moet worden
    /// </summary>
    /// <param name="kolomNr">Het tabelkolomnummer van de gevraagde kolom</param>
    /// <returns>true indien vergelijken toegestaan / mogelijk is anders false</returns>
