    public int AantalRijen(int stuIndexBegin, int stuIndexEinde, int[]? filterLijst)
    {
        // Deze tabel is ongefilterd
        return stuIndexEinde - Math.Max(1, stuIndexBegin);  // Max: Rootelement niet meetellen
    }

    /// <summary>
    /// Bepaal de index in de structuurlijst van de begroting die overeenkomt met het opgegeven rijnummer
    /// </summary>
    /// <param name="rijNr">Nummer van de rij. Voor de eerste rij geldt: rijNr == 0</param>
    /// <returns>Index in de structuurlijst van de begroting</returns>
    public int StuIndex(int rijNr)
    {
        // Het filter, het rijnummer en de structuurlijst beginnen alle te nummeren bij 0
        // Wanneer geen filter is toegepast komt de eerste rij overeen met het tweede element
        // in de structuurlijst, omdat het rootelement wordt overgeslagen.
        if (rijNr == 0 && m_Structuur._Aantal == 1)
            return 0;

        return rijNr + 1; // Het rootelement niet meetellen
    }
